ALTER SERVER foo OPTIONS (host 'foo', dbname 'foodb');

ALTER SERVER foo VERSION '8.4' OPTIONS (SET host 'baz');

ALTER SERVER foo VERSION '9.1';

ALTER SERVER foo OWNER TO bob;

ALTER SERVER foo OWNER TO CURRENT_USER;

ALTER SERVER foo RENAME TO bar;

DROP SERVER foo;

DROP SERVER IF EXISTS foo, bar CASCADE;

ALTER USER MAPPING FOR bob SERVER foo OPTIONS (SET password 'public');

ALTER USER MAPPING FOR CURRENT_USER SERVER foo OPTIONS (ADD user 'bob', DROP password);

ALTER USER MAPPING FOR PUBLIC SERVER foo OPTIONS (SET user 'guest');

DROP USER MAPPING FOR bob SERVER foo;

DROP USER MAPPING IF EXISTS FOR PUBLIC SERVER foo;

ALTER FOREIGN DATA WRAPPER dbi OPTIONS (ADD foo '1', DROP bar);

ALTER FOREIGN DATA WRAPPER dbi VALIDATOR bob.myvalidator;

ALTER FOREIGN DATA WRAPPER dbi HANDLER dbi_handler NO VALIDATOR;

ALTER FOREIGN DATA WRAPPER dbi NO HANDLER OPTIONS (SET debug 'true');

ALTER FOREIGN DATA WRAPPER dbi OWNER TO SESSION_USER;

ALTER FOREIGN DATA WRAPPER dbi RENAME TO dbi2;

DROP FOREIGN DATA WRAPPER dbi;

DROP FOREIGN DATA WRAPPER IF EXISTS dbi, dbi2 RESTRICT;
